const normalizeSources = (rows) => rows.map(([id, label, url, publisher]) => ({ id, label, url, publisher, type: 'faglig_eller_primar_kilde', source_location: 'Verk-, prosjekt-, rapport- eller institusjonspresentasjon' }));
const makeParagraph = (spec, index) => {
  const object = spec.objects[index % spec.objects.length];
  const theory = spec.theories[index % spec.theories.length];
  const method = spec.methods[index % spec.methods.length];
  const history = spec.history[index % spec.history.length];
  const geography = spec.geo[index % spec.geo.length];
  const boundaries = spec.bounds.map((id) => id.replaceAll('_', ' ')).join(', ');
  const paragraph = `Artikkelen behandler ${spec.sub[index]} som et eget analytisk problem innen ${spec.title.toLowerCase()}. I ${object} kan ${method} anvendes sammen med ${theory} for å undersøke hvordan materialet er produsert, hvilke relasjoner eller formtrekk det organiserer, og hvilken slutning evidensen faktisk bærer. Sammenstillingen plasseres mellom ${history} og ${geography}, men tids-, språk- og stedsforskjellen behandles som forklaringsvariabel. ${depth[index]} Resultatet avgrenses eksplisitt mot ${boundaries}, slik at nabofagets spørsmål ikke brukes som erstatning for områdets egen evidens.`;
  if (words(paragraph) < 55) throw new Error(`${spec.id}: kort avsnitt ${index}`);
  return paragraph;
};

